 * Covers prefilled fields, saving, cancellation, validation, retries, busy state,
 * ownership filtering and restrictions for closed or already-joined lotteries.
 * Uses fake repositories and a fixed clock; no writes to live Firebase.
 * Requires an Android emulator or device. Native pickers are not automated here.
 */
package com.example.code.ui.owner

import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.mutableStateOf
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.assertIsEnabled
import androidx.compose.ui.test.assertIsNotEnabled
import androidx.compose.ui.test.assertIsOn
import androidx.compose.ui.test.assertTextContains
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onAllNodesWithText
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.performScrollTo
import androidx.compose.ui.test.performTextReplacement
import com.example.code.controller.LotteryUpdateController
import com.example.code.data.LotteryUpdateRepository
import com.example.code.model.Campsite
import com.example.code.model.Lottery
import com.example.code.navigation.OwnerLotteriesRoute
import kotlinx.coroutines.CompletableDeferred
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test

class EditLotteryUiTest {
    @get:Rule val compose = createComposeRule()
    private val owner = "owner-device"
    private val first = Campsite(id = "site-a", ownerId = owner, name = "Pine Creek")
    private val second = Campsite(id = "site-b", ownerId = owner, name = "River Bend")
    private val original = Lottery(
        id = "lottery-a", ownerId = owner, campsiteId = first.id, campsiteName = first.name,
        registrationStart = 1_000L, registrationEnd = 2_000L,
        bookingStart = 3_000L, bookingEnd = 4_000L, winnerCount = 3, waitlistCapacity = 10,
    )
    private val now = { 500L }
    private inner class Repository : LotteryUpdateRepository {
        val current = mutableStateOf(original)
        var calls = 0
        var fail = false
        var gate: CompletableDeferred<Unit>? = null
        override suspend fun updateLottery(original: Lottery, ownerId: String, changes: Lottery) {
            calls++
            gate?.await()
            if (fail) error("Simulated save failure")
            val sites = listOf(first, second).filter { site ->
                com.example.code.controller.LotteryController.includesCampsite(changes, site.id)
            }
            current.value = LotteryUpdateController.revalidate(
                original, current.value, ownerId, sites, changes, now(),
            )
        }
    }
    private fun showRoute(repository: Repository) {
        compose.setContent {
            MaterialTheme {
                OwnerLotteriesRoute(
                    lotteries = listOf(repository.current.value), deviceId = owner,
                    onOpenWaitingList = {}, campsites = listOf(first, second),
                    updateRepository = repository, clock = now,
                )
            }
        }
        compose.onNodeWithTag("edit-lottery-${original.id}").performScrollTo().performClick()
    }

    @Test fun editorPrefillsFieldsAndSaveRefreshesTheExistingListing() {
        val repo = Repository()
        showRoute(repo)
        compose.onNodeWithTag("edit-lottery-campsite-${first.id}").assertIsOn()
        compose.onNodeWithTag("editLotteryWinners").performScrollTo().assertTextContains("3")
            .performTextReplacement("4")
        compose.onNodeWithTag("editLotteryCapacity").assertTextContains("10")
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("Lottery updated.").assertIsDisplayed()
        compose.onNodeWithText("Winners: 4").performScrollTo().assertIsDisplayed()
        compose.runOnIdle { assertEquals(1, repo.calls); assertEquals(original.id, repo.current.value.id) }
        compose.onNodeWithTag("edit-lottery-${original.id}").performScrollTo().performClick()
        compose.onNodeWithTag("editLotteryWinners").performScrollTo().assertTextContains("4")
    }

    @Test fun cancelDiscardsUnsavedChanges() {
        val repo = Repository()
        showRoute(repo)
        compose.onNodeWithTag("editLotteryWinners").performScrollTo().performTextReplacement("4")
        compose.onNodeWithTag("cancelLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("My lotteries").assertIsDisplayed()
        compose.runOnIdle { assertEquals(0, repo.calls); assertEquals(3, repo.current.value.winnerCount) }
    }

    @Test fun invalidWinnerCountDoesNotReachPersistence() {
        val repo = Repository()
        showRoute(repo)
        compose.onNodeWithTag("editLotteryWinners").performScrollTo().performTextReplacement("0")
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("Choose at least one winner.").performScrollTo().assertIsDisplayed()
        compose.runOnIdle { assertEquals(0, repo.calls) }
    }

    @Test fun saveFailureKeepsValuesAndAllowsRetry() {
        val repo = Repository().apply { fail = true }
        showRoute(repo)
        compose.onNodeWithTag("editLotteryWinners").performScrollTo().performTextReplacement("4")
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("Could not update lottery: Simulated save failure")
            .performScrollTo().assertIsDisplayed()
        compose.onNodeWithTag("editLotteryWinners").assertTextContains("4")
        compose.runOnIdle { repo.fail = false }
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("Lottery updated.").assertIsDisplayed()
        compose.runOnIdle { assertEquals(2, repo.calls); assertEquals(4, repo.current.value.winnerCount) }
    }

    @Test fun pendingSaveDisablesSaveAndCancel() {
        val gate = CompletableDeferred<Unit>()
        val repo = Repository().apply { this.gate = gate }
        showRoute(repo)
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        try {
            compose.onNodeWithTag("saveLotteryChanges").assertIsNotEnabled()
            compose.onNodeWithTag("cancelLotteryChanges").assertIsNotEnabled()
            compose.runOnIdle { assertEquals(1, repo.calls) }
        } finally {
            compose.runOnIdle { gate.complete(Unit) }
        }
        compose.onNodeWithText("Lottery updated.").assertIsDisplayed()
    }

    @Test fun editorHidesOtherOwnersCampsitesAndLocksExistingEntrantsStay() {
        val current = original.copy(waitingListCount = 4)
        compose.setContent {
            MaterialTheme {
                EditLotteryScreen(
                    lottery = current, ownerId = owner,
                    campsites = listOf(first, second, second.copy(id = "foreign", ownerId = "other")),
                    onSave = { _, _ -> }, onSaved = {}, onCancel = {}, clock = now,
                )
            }
        }
        compose.onNodeWithTag("edit-lottery-campsite-foreign").assertDoesNotExist()
        compose.onNodeWithTag("edit-lottery-campsite-${first.id}").assertIsNotEnabled()
        compose.onNodeWithTag("edit-lottery-campsite-${second.id}").assertIsNotEnabled()
        compose.onAllNodesWithText("Choose", useUnmergedTree = true)[2]
            .performScrollTo().assertIsNotEnabled()
        compose.onNodeWithTag("editLotteryCapacity").performScrollTo().performTextReplacement("3")
        compose.onNodeWithTag("saveLotteryChanges").performScrollTo().performClick()
        compose.onNodeWithText("Waiting-list capacity cannot be below the number of entrants already joined.")
            .performScrollTo().assertIsDisplayed()
    }

    @Test fun closedAndDrawnListingsCannotOpenEditor() {
        compose.setContent {
            MaterialTheme {
                OwnerLotteriesScreen(
                    lotteries = listOf(original.copy(status = Lottery.STATUS_DRAWN),
                        original.copy(id = "closed", registrationEnd = 500L)),
                    onOpenWaitingList = {}, onEditLottery = { error("Cannot edit") }, now = now(),
                )
            }
        }
        compose.onNodeWithTag("edit-lottery-${original.id}").performScrollTo().assertIsNotEnabled()
        compose.onNodeWithTag("edit-lottery-closed").performScrollTo().assertIsNotEnabled()
    }
}
